package rules

import "testing"

// Cases ported from ECS's MethodChainingNewlineFixerTest fixtures
// (packages/coding-standard/tests/Fixer/Spacing/MethodChainingNewlineFixer/Fixture);
// every expected output is what the Symplify fixer produces for the input.
func TestMethodChainingNewlineCases(t *testing.T) {
	t.Parallel()
	aliasRunUpstreamCases(t, MethodChainingNewline{}, []aliasUpstreamCase{
		{"many_multi_line_chain_with_args", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nclass ManyMultiLineChain\n{\n    public function run($treeNodeEntity)\n    {\n        $childChildItem = $treeNodeEntity->getChildNodes()->get(0)->getChildNodes();\n    }\n}\n\n?>\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nclass ManyMultiLineChain\n{\n    public function run($treeNodeEntity)\n    {\n        $childChildItem = $treeNodeEntity->getChildNodes()\n->get(0)\n->getChildNodes();\n    }\n}\n\n?>\n"},
		{"skip_another_line_bracket", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Source\\SomeClassWithChains;\n\nclass SkipAnotherLineBracket\n{\n    public function run(SomeClassWithChains $someClassWithChains)\n    {\n        return $someClassWithChains->two([\n                'hey' => 'hou'\n            ])->three();\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Source\\SomeClassWithChains;\n\nclass SkipAnotherLineBracket\n{\n    public function run(SomeClassWithChains $someClassWithChains)\n    {\n        return $someClassWithChains->two([\n                'hey' => 'hou'\n            ])->three();\n    }\n}\n"},
		{"skip_boolean_chain", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse PHPStan\\Type\\Type;\n\nclass SkipBooleanChain\n{\n    public function run(Type $paramType): bool\n    {\n        if (\n            $paramType->isInteger()->yes()\n            || $paramType->isBoolean()->yes()\n            || $paramType->isNumericString()->yes()\n        ) {\n            return true;\n        }\n\n        return false;\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse PHPStan\\Type\\Type;\n\nclass SkipBooleanChain\n{\n    public function run(Type $paramType): bool\n    {\n        if (\n            $paramType->isInteger()->yes()\n            || $paramType->isBoolean()->yes()\n            || $paramType->isNumericString()->yes()\n        ) {\n            return true;\n        }\n\n        return false;\n    }\n}\n"},
		{"skip_clone_call", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse DateTime;\n\nclass SkipCloneCall\n{\n    public function run(DateTime $dateTime)\n    {\n        (clone $dateTime)->format('date');\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse DateTime;\n\nclass SkipCloneCall\n{\n    public function run(DateTime $dateTime)\n    {\n        (clone $dateTime)->format('date');\n    }\n}\n"},
		{"skip_comparison_chain", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse PHPStan\\Reflection\\MethodReflection;\n\nclass SkipComparisonChain\n{\n    public function isMethodSupported(MethodReflection $methodReflection): bool\n    {\n        return $methodReflection->getDeclaringClass()->getName() === ObjectDataMapper::class\n            && $methodReflection->getName() === 'map';\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse PHPStan\\Reflection\\MethodReflection;\n\nclass SkipComparisonChain\n{\n    public function isMethodSupported(MethodReflection $methodReflection): bool\n    {\n        return $methodReflection->getDeclaringClass()->getName() === ObjectDataMapper::class\n            && $methodReflection->getName() === 'map';\n    }\n}\n"},
		{"skip_concat", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse PharIo\\Version\\Version;\n\nclass SkipConcat\n{\n    public function run(Version $lastStableVersion)\n    {\n        return $this->symplifyVersionToRequire = '^' . $lastStableVersion->getMajor()->getValue() . '.' . $lastStableVersion->getMinor()->getValue();\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse PharIo\\Version\\Version;\n\nclass SkipConcat\n{\n    public function run(Version $lastStableVersion)\n    {\n        return $this->symplifyVersionToRequire = '^' . $lastStableVersion->getMajor()->getValue() . '.' . $lastStableVersion->getMinor()->getValue();\n    }\n}\n"},
		{"skip_func_call_args_single_method", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nclass SkipFuncCallArgsSingleMethod\n{\n    public function run()\n    {\n        config('here', [])->set('this', 'that');\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nclass SkipFuncCallArgsSingleMethod\n{\n    public function run()\n    {\n        config('here', [])->set('this', 'that');\n    }\n}\n"},
		{"skip_func_call_single_method", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nclass SkipFuncCallSingleMethod\n{\n    public function run()\n    {\n        return app()->one();\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nclass SkipFuncCallSingleMethod\n{\n    public function run()\n    {\n        return app()->one();\n    }\n}\n"},
		{"skip_func_call_single_method_with_args", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nclass SkipFuncCallSingleMethodWithArgs\n{\n    public function run()\n    {\n        config()->set('this', 'that');\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nclass SkipFuncCallSingleMethodWithArgs\n{\n    public function run()\n    {\n        config()->set('this', 'that');\n    }\n}\n"},
		{"skip_func_call_single_method_with_array", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nclass SkipFuncCallSingleMethodWithArray\n{\n    public function run()\n    {\n        config()->set();\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nclass SkipFuncCallSingleMethodWithArray\n{\n    public function run()\n    {\n        config()->set();\n    }\n}\n"},
		{"skip_func_call_with_method_call", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nclass SkipFuncCallWithMethodCall\n{\n    public function run($one, $two)\n    {\n        return inline_service($one)->args($two);\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nclass SkipFuncCallWithMethodCall\n{\n    public function run($one, $two)\n    {\n        return inline_service($one)->args($two);\n    }\n}\n"},
		{"skip_in_array", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse PharIo\\Version\\Version;\n\nclass SkipInArray\n{\n    public function run(Version $version)\n    {\n        return [$version->getMajor()->getValue()];\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse PharIo\\Version\\Version;\n\nclass SkipInArray\n{\n    public function run(Version $version)\n    {\n        return [$version->getMajor()->getValue()];\n    }\n}\n"},
		{"skip_in_array_more", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse PharIo\\Version\\Version;\n\nclass SkipInArrayMore\n{\n    public function run(Version $version, array $values)\n    {\n        $values[$version->getMajor()->getValue()];\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse PharIo\\Version\\Version;\n\nclass SkipInArrayMore\n{\n    public function run(Version $version, array $values)\n    {\n        $values[$version->getMajor()->getValue()];\n    }\n}\n"},
		{"skip_in_call", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse PharIo\\Version\\Version;\n\nclass SkipInCall\n{\n    public function run(Version $version)\n    {\n        return $this->again($version->getMajor()->getValue());\n    }\n\n    public function again()\n    {\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse PharIo\\Version\\Version;\n\nclass SkipInCall\n{\n    public function run(Version $version)\n    {\n        return $this->again($version->getMajor()->getValue());\n    }\n\n    public function again()\n    {\n    }\n}\n"},
		{"skip_maybe_trailing_method", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Source\\SomeClassWithChains;\n\nclass SkipMaybeTrailingMethod\n{\n    public function run(SomeClassWithChains $someClassWithChains)\n    {\n        return $someClassWithChains->one()->maybe();\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Source\\SomeClassWithChains;\n\nclass SkipMaybeTrailingMethod\n{\n    public function run(SomeClassWithChains $someClassWithChains)\n    {\n        return $someClassWithChains->one()->maybe();\n    }\n}\n"},
		{"skip_multi_line_chain", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nclass SkipMultiLineChain\n{\n    public function run()\n    {\n        return $this->one()\n            ->two();\n    }\n\n    public function one()\n    {\n        return $this;\n    }\n\n    public function two()\n    {\n        return $this;\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nclass SkipMultiLineChain\n{\n    public function run()\n    {\n        return $this->one()\n            ->two();\n    }\n\n    public function one()\n    {\n        return $this;\n    }\n\n    public function two()\n    {\n        return $this;\n    }\n}\n"},
		{"skip_short_method_in_if_condition", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse PHPStan\\Type\\Type;\n\nclass SkipShortMethodInIfCondition\n{\n    public function run(Type $paramType): bool\n    {\n        if ($paramType->isInteger()->yes()) {\n            return true;\n        }\n\n        return false;\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse PHPStan\\Type\\Type;\n\nclass SkipShortMethodInIfCondition\n{\n    public function run(Type $paramType): bool\n    {\n        if ($paramType->isInteger()->yes()) {\n            return true;\n        }\n\n        return false;\n    }\n}\n"},
		{"skip_short_noarg_three_chain", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Source\\SomeClassWithChains;\n\nclass ManyMultiLineChain\n{\n    public function run(SomeClassWithChains $someClassWithChains)\n    {\n        return $someClassWithChains->one()->two()->three();\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Source\\SomeClassWithChains;\n\nclass ManyMultiLineChain\n{\n    public function run(SomeClassWithChains $someClassWithChains)\n    {\n        return $someClassWithChains->one()->two()->three();\n    }\n}\n"},
		{"skip_short_noarg_two_chain", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Source\\SomeClassWithChains;\n\nclass MultiLineChain\n{\n    public function run(SomeClassWithChains $someClassWithChains)\n    {\n        return $someClassWithChains->one()->two();\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Source\\SomeClassWithChains;\n\nclass MultiLineChain\n{\n    public function run(SomeClassWithChains $someClassWithChains)\n    {\n        return $someClassWithChains->one()->two();\n    }\n}\n"},
		{"skip_single_call_on_instantiation", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nclass SkipSingleCallOnInstantiation\n{\n    public function run()\n    {\n        return (new self())->one();\n    }\n\n    public function one()\n    {\n        return $this;\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nclass SkipSingleCallOnInstantiation\n{\n    public function run()\n    {\n        return (new self())->one();\n    }\n\n    public function one()\n    {\n        return $this;\n    }\n}\n"},
		{"skip_static_call_date_time", nil, "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse Nette\\Utils\\DateTime;\n\nclass SkipStaticCallDateTime\n{\n    public function run()\n    {\n        $starts_date = DateTime::from('now')->getOffset();\n\n        $starts_date = DateTime::from()->getOffset();\n    }\n}\n", "<?php\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\Spacing\\MethodChainingNewlineFixer\\Fixture;\n\nuse Nette\\Utils\\DateTime;\n\nclass SkipStaticCallDateTime\n{\n    public function run()\n    {\n        $starts_date = DateTime::from('now')->getOffset();\n\n        $starts_date = DateTime::from()->getOffset();\n    }\n}\n"},
	})
}
